def generate_horizontal_bar(data, title, value_key=None, color="#4F46E5"):
    items = list(data.items())
    # If data contains dict values (like country_summary with 'avg_risk', 'avg_salary' etc.)
    if isinstance(items[0][1], dict):
        if value_key:
            items = [(k, v[value_key]) for k, v in items]
        else:
            items = [(k, v.get('avg_risk', v.get('avg_salary', 0))) for k, v in items]

    width = 600
    height = 40 + len(items) * 35
    max_val = max(v for _, v in items) if items else 1

